import pandas as pd
import numpy as np

def calculate_trapped_rain_water(heights: pd.DataFrame) -> pd.DataFrame:
    if heights.empty:
        return pd.DataFrame({'total_trapped_water': [0]})
    df = heights.sort_values(by='id').reset_index(drop=True)
    left_max = df['height'].cummax()
    right_max = df['height'].iloc[::-1].cummax().iloc[::-1]
    water = np.maximum(0, np.minimum(left_max, right_max) - df['height'])
    return pd.DataFrame({'total_trapped_water': [int(water.sum())]})
